CREATE TABLE public.performance_samples (
 session_key uuid NOT NULL, minute timestamptz NOT NULL DEFAULT date_trunc('minute',now()), received_at timestamptz NOT NULL DEFAULT now(), cache_hits integer NOT NULL, cache_misses integer NOT NULL, requests integer NOT NULL, errors integer NOT NULL, latency_total numeric NOT NULL, latency_max numeric NOT NULL, realtime_connections integer NOT NULL CHECK(realtime_connections BETWEEN 0 AND 1), PRIMARY KEY(session_key,minute)
);
GRANT SELECT ON public.performance_samples TO authenticated;
GRANT ALL ON public.performance_samples TO service_role;
ALTER TABLE public.performance_samples ENABLE ROW LEVEL SECURITY;
CREATE POLICY performance_manager_read ON public.performance_samples FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE INDEX performance_samples_date ON public.performance_samples(received_at);
CREATE OR REPLACE FUNCTION public.record_performance_sample(_session uuid,_hits integer,_misses integer,_requests integer,_errors integer,_latency_total numeric,_latency_max numeric,_connections integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _hits NOT BETWEEN 0 AND 1000 OR _misses NOT BETWEEN 0 AND 1000 OR _requests NOT BETWEEN 0 AND 1000 OR _errors NOT BETWEEN 0 AND _requests OR _latency_total NOT BETWEEN 0 AND 60000000 OR _latency_max NOT BETWEEN 0 AND 60000 OR _connections NOT BETWEEN 0 AND 1 THEN RAISE EXCEPTION 'Invalid sample'; END IF; INSERT INTO public.performance_samples(session_key,cache_hits,cache_misses,requests,errors,latency_total,latency_max,realtime_connections) VALUES(_session,_hits,_misses,_requests,_errors,_latency_total,_latency_max,_connections) ON CONFLICT DO NOTHING; IF NOT FOUND THEN RETURN false; END IF; DELETE FROM public.performance_samples WHERE received_at < now()-interval '24 hours'; RETURN true; END; $$;
REVOKE ALL ON FUNCTION public.record_performance_sample(uuid,integer,integer,integer,integer,numeric,numeric,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.record_performance_sample(uuid,integer,integer,integer,integer,numeric,numeric,integer) TO service_role;
CREATE OR REPLACE FUNCTION public.admin_performance_summary() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT jsonb_build_object('cache_hits',coalesce(sum(cache_hits),0),'cache_misses',coalesce(sum(cache_misses),0),'requests',coalesce(sum(requests),0),'errors',coalesce(sum(errors),0),'latency_total',coalesce(sum(latency_total),0),'latency_max',coalesce(max(latency_max),0),'samples',count(*),'last_received',max(received_at)) INTO result FROM public.performance_samples WHERE received_at>=now()-interval '15 minutes'; RETURN result || jsonb_build_object('active_visits',(SELECT count(*) FROM (SELECT DISTINCT ON(session_key) session_key,realtime_connections FROM public.performance_samples WHERE received_at>=now()-interval '90 seconds' ORDER BY session_key,received_at DESC) live),'realtime_connections',(SELECT coalesce(sum(realtime_connections),0) FROM (SELECT DISTINCT ON(session_key) session_key,realtime_connections FROM public.performance_samples WHERE received_at>=now()-interval '90 seconds' ORDER BY session_key,received_at DESC) live)); END; $$;
REVOKE ALL ON FUNCTION public.admin_performance_summary() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_performance_summary() TO authenticated;